SELECT ?sensor ?label ?ts WHERE {
  ?tsRef a ref:TimeseriesReference ; ref:hasTimeseriesId ?ts .
  ?sensor ref:hasExternalReference ?tsRef ; 
    brick:isPointOf ?zone .
  FILTER (regex(str(?sensor), "Zone.*Air_Temperature_Sensor"))
  OPTIONAL { ?sensor rdfs:label ?label }
} ORDER BY ?sensor

